python -c "import pandas as pd, numpy as np; d=pd.read_csv('data/vehicle_positions_gps_only.csv.gz'); d=d.sort_values(['device_id','timestamp']); d['timestamp']=pd.to_datetime(d['timestamp']); g=d.groupby('device_id'); dt=g['timestamp'].diff().dt.total_seconds(); lat=g['latitude'].diff(); lon=g['longitude'].diff(); dy=np.radians(lat)*6371000; dx=np.radians(lon)*6371000*np.cos(np.radians(d['latitude'])); s=np.sqrt(dx**2+dy**2)/dt; s=s[(dt>0)&(dt<=1.01)&s.notna()]; print('Records:',len(d),'Devices:',d.device_id.nunique(),'Speed samples:',len(s)); print('Mean:',round(s.mean(),2),'m/s'); print('Median:',round(s.median(),2),'m/s'); print('75th:',round(s.quantile(.75),2),'m/s'); print('90th:',round(s.quantile(.90),2),'m/s'); print('95th:',round(s.quantile(.95),2),'m/s'); print('Maximum:',round(s.max(),2),'m/s'); print('Below 10 km/h:',round((s<10/3.6).mean()*100,2),'%'); print('10-30 km/h:',round(((s>=10/3.6)&(s<30/3.6)).mean()*100,2),'%'); print('30-50 km/h:',round(((s>=30/3.6)&(s<50/3.6)).mean()*100,2),'%'); print('Above 50 km/h:',round((s>=50/3.6).mean()*100,2),'%')"